INSERT INTO `videos` (`id`, `youtube_url`, `titulo`, `descripcion`, `duracion`, `fecha_publicacion`, `iframe_codigo`, `fecha_agregado`) VALUES (NULL, 'https://www.youtube.com/watch?v=65KJf-vtt9I&t=434s', 'Proyecto Activa El Turismo', 'Proyecto Activa El Turismo Invitado el Seremi de Cultura Región Antofagasta Claudio Lagos', '39:11', '2022-06-07', '<iframe width=\"100%\" height=\"320\" src=\"https://www.youtube.com/embed/65KJf-vtt9I\" title=\"YouTube video player\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" allowfullscreen loading=\"lazy\"></iframe>', '2026-07-14 12:59:28'), (NULL, 'https://www.youtube.com/watch?v=9g1RIYwKHNA', '#Antofagasta | #Taltal | #Calama | #Tocopilla Hoy Junto a Raul Soto de Trasportes Conomar', '#Antofagasta | #Taltal | #Calama | #Tocopilla El dia de Hoy Hablaremos con Raul Soto Lay Dueño de la empresa de Trasportes Conomar LTDA', '39:24', '2022-06-21T14:00:08-07:00', '<iframe width=\"100%\" height=\"320\" src=\"https://www.youtube.com/embed/9g1RIYwKHNA\" title=\"YouTube video player\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" allowfullscreen loading=\"lazy\"></iframe>', '2026-07-14 12:59:40'), (NULL, 'https://www.youtube.com/watch?v=I2BokuAdx8A', 'Hoy Hablaremos patrimonio y las características de su normativa para su protección regional', 'En este capítulo abordamos el concepto de patrimonio y las características de su normativa para su protección, Ademas precisamos las categorías que posee es...', '26:39', '2022-07-06T14:00:16-07:00', '<iframe width=\"100%\" height=\"320\" src=\"https://www.youtube.com/embed/I2BokuAdx8A\" title=\"YouTube video player\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" allowfullscreen loading=\"lazy\"></iframe>', '2026-07-14 12:59:48'), (NULL, 'https://www.youtu